def align(seq_a: str, seq_b: str, mode: str = "global",
          match: int = 2, mismatch: int = -3,
          gap_open: int = -5, gap_extend: int = -2) -> tuple[int, str, str]:
    # Handle empty sequences
    if not seq_a and not seq_b:
        return (0, "", "")
    if not seq_a:
        return (0, "", seq_b)
    if not seq_b:
        return (0, seq_a, "")

    # Initialize DP table
    len_a, len_b = len(seq_a), len(seq_b)
    dp = [[0] * (len_b + 1) for _ in range(len_a + 1)]

    # Initialize first row and column based on mode
    if mode == "global":
        # Global mode: fill first row and column with gap costs
        for j in range(1, len_b + 1):
            dp[0][j] = gap_open + (j - 1) * gap_extend
        for i in range(1, len_a + 1):
            dp[i][0] = gap_open + (i - 1) * gap_extend
    else:  # local mode
        # Local mode: no initialization needed, as the DP table is filled with max values
        pass

    # Fill DP table
    for i in range(1, len_a + 1):
        for j in range(1, len_b + 1):
            # Compute match/mismatch score
            if seq_a[i-1] == seq_b[j-1]:
                score = match
            else:
                score = mismatch
            # Compute the three possibilities
            option1 = dp[i-1][j-1] + score
            option2 = dp[i-1][j] + gap_extend
            option3 = dp[i][j-1] + gap_extend
            # For local mode, add the option of starting a new alignment (0)
            if mode == "local":
                option4 = 0
                dp[i][j] = max(option1, option2, option3, option4)
            else:
                dp[i][j] = max(option1, option2, option3)

    # Backtrack to find the alignment
    # Determine the starting point
    if mode == "global":
        i, j = len_a, len_b
    else:
        # Find the maximum value in the DP table
        max_score = 0
        max_i, max_j = 0, 0
        for i in range(len_a + 1):
            for j in range(len_b + 1):
                if dp[i][j] > max_score:
                    max_score = dp[i][j]
                    max_i, max_j = i, j
        i, j = max_i, max_j

    # Initialize aligned sequences
    aligned_a = []
    aligned_b = []

    # Backtrack
    while i > 0 and j > 0:
        # Compute the three options
        if seq_a[i-1] == seq_b[j-1]:
            score = match
        else:
            score = mismatch
        option1 = dp[i-1][j-1] + score
        option2 = dp[i-1][j] + gap_extend
        option3 = dp[i][j-1] + gap_extend

        if dp[i][j] == option1:
            # Match/mismatch
            aligned_a.append(seq_a[i-1])
            aligned_b.append(seq_b[j-1])
            i -= 1
            j -= 1
        elif dp[i][j] == option2:
            # Gap in a
            aligned_a.append('-')
            aligned_b.append(seq_b[j-1])
            i -= 1
        else:
            # Gap in b
            aligned_a.append(seq_a[i-1])
            aligned_b.append('-')
            j -= 1

    # Reverse the aligned sequences
    aligned_a.reverse()
    aligned_b.reverse()

    # Return the score and aligned sequences
    if mode == "global":
        score = dp[len_a][len_b]
    else:
        score = max_score

    return (score, ''.join(aligned_a), ''.join(aligned_b))

